package com.uklanafood.restaurant;

import android.app.NotificationChannel;import android.app.NotificationManager;import android.app.PendingIntent;import android.content.Context;import android.content.Intent;import android.media.AudioAttributes;import android.os.Build;import androidx.core.app.NotificationCompat;
public final class NotificationHelper{
 private NotificationHelper(){}
 public static void show(Context c,String title,String body){NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);String channel=AppConfig.CHANNEL_ID+Math.abs(RingtoneHelper.getSelectedUri(c).toString().hashCode());if(Build.VERSION.SDK_INT>=26){NotificationChannel ch=new NotificationChannel(channel,"Restaurant Order Alerts",NotificationManager.IMPORTANCE_HIGH);ch.setSound(RingtoneHelper.getSelectedUri(c),new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_ALARM).build());ch.enableVibration(true);nm.createNotificationChannel(ch);}Intent i=new Intent(c,MainActivity.class);i.addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent pi=PendingIntent.getActivity(c,0,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);NotificationCompat.Builder b=new NotificationCompat.Builder(c,channel).setSmallIcon(R.drawable.ic_app).setContentTitle(title).setContentText(body).setStyle(new NotificationCompat.BigTextStyle().bigText(body)).setPriority(NotificationCompat.PRIORITY_MAX).setAutoCancel(true).setContentIntent(pi).setSound(RingtoneHelper.getSelectedUri(c)).setVibrate(new long[]{0,800,250,800});nm.notify((int)(System.currentTimeMillis()%100000),b.build());}
}
